head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > enableAllDate]<br/>inputType 이 'calendar' 인 Body Column 의 팝업 달력에 적용된 날짜 비활성 제한을 모두 제거합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 날짜 비활성 제한을 제거할 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "inputType 이 'calendar' 인 Body Column 에서만 팝업 달력의 날짜 비활성 제한(disableBeforeDate / disableAfterDate)이 모두 제거됩니다.",
        "팝업 달력의 날짜 비활성 제한은 Column 단위로 적용되며 Row 단위로 적용할 수 없습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] 인덱스 2 = calendar 컬럼(col3), 1/10 이전·1/20 이후 팝업 달력 비활성. 인덱스 1(col2)은 숨김 컬럼(인덱스에 포함).\n[절차] calendar 셀 편집 진입 후 달력 아이콘으로 팝업 오픈 -> 비활성일 확인 -> par_columnInfo=2 로 enableAllDate -> 팝업 재오픈 후 비활성일 확인.\n[확인] 팝업 비활성일 개수가 enableAllDate 전 N개 -> 후 0개."', '', 'label1');

    // 본문 데이터리스트 : col3 은 dataType=date (calendar 컬럼 값 오염 방지). 날짜값은 순수 yyyyMMdd.
    let strNameSpace = $c.gcm.getNameSpace();
    let dlXml = '';
    dlXml += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map" saveRemovedData="true">';
    dlXml += '<w2:columnInfo>';
    dlXml += '<w2:column id="col1" name="이름" dataType="text"></w2:column>';
    dlXml += '<w2:column id="col2" name="코드" dataType="text"></w2:column>';
    dlXml += '<w2:column id="col3" name="날짜" dataType="date"></w2:column>';
    dlXml += '<w2:column id="col4" name="비고" dataType="text"></w2:column>';
    dlXml += '</w2:columnInfo>';
    dlXml += '<w2:data use="true">';
    dlXml += '<w2:row><col1>홍길동</col1><col2>A01</col2><col3>20260112</col3><col4>메모A</col4></w2:row>';
    dlXml += '<w2:row><col1>김철수</col1><col2>A02</col2><col3>20260115</col3><col4>메모B</col4></w2:row>';
    dlXml += '<w2:row><col1>이영희</col1><col2>A03</col2><col3>20260118</col3><col4>메모C</col4></w2:row>';
    dlXml += '<w2:row><col1>박민준</col1><col2>A04</col2><col3>20260114</col3><col4>메모D</col4></w2:row>';
    dlXml += '</w2:data>';
    dlXml += '</w2:dataList>';
    $p.data.create(dlXml);

    // target 생성
    //  col3 = inputType=calendar(dataType=date, viewType=icon, calendarValueType=yearMonthDate, displayFormat=yyyy-MM-dd)
    //         disableBeforeDate / disableAfterDate 로 팝업 달력에 날짜 범위 비활성 제한을 미리 설정.
    //  editable=true 로 셀 편집(팝업 달력 진입) 허용. 나머지 col1/col2/col4 = text.
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" editable="true" dataList="data:dlt_bind" id="" style="width:620px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="120" inputType="text" id="hcol1" value="col1 이름 (text)"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol2" value="col2 코드 (text/숨김)"></w2:column>';
    strTarget += '<w2:column width="180" inputType="text" id="hcol3" value="col3 날짜 (calendar)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4 비고 (text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="120" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="180" inputType="calendar" dataType="date" viewType="icon" calendarValueType="yearMonthDate" displayFormat="yyyy-MM-dd" disableBeforeDate="20260110" disableAfterDate="20260120" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // col2(인덱스 1) Column 을 숨김 처리 : columnInfo 인덱스가 숨겨진 Column 도 포함함을 검증하기 위함.
    scwin.target1.setColumnVisible(1, false);
}



// enableAllDate 실행 : inputType=calendar 컬럼의 팝업 달력 날짜 비활성 제한(disableBeforeDate/disableAfterDate)을 모두 제거 (1인자, columnInfo=인덱스)
//  주 검증은 [비활성일 확인] 의 팝업 비활성일 개수 변화(전 N개 -> 후 0개). 여기서는 옵션 제거 결과를 보조로 한 줄 출력.
scwin.btn_enableAllDate_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let inputType = scwin.target1.getCellInfo(columnInfo).options.inputType;

    let ret = scwin.target1.enableAllDate(columnInfo);

    let afterOptions = scwin.target1.getCellInfo(columnInfo).options;

    wf_body_bottom.getObj("scwin").setReturnValue(inputType === "calendar"
        ? "enableAllDate(" + columnInfo + ") 실행 -> disableBeforeDate='" + afterOptions.disableBeforeDate + "' / disableAfterDate='" + afterOptions.disableAfterDate + "' (제거됨). 팝업 재오픈 후 비활성일 확인 시 0개"
        : "enableAllDate(" + columnInfo + ") -> calendar 아닌 컬럼(inputType=" + inputType + ") : 미동작(반환 " + ret + ")");
}



// 비활성일 확인(주 검증 수단) : 열려 있는 grid calendar 팝업 달력의 취소선(비활성) 날짜 셀(class w2calendar_date_disable) textContent 목록을 출력.
//  enableAllDate 전에는 날짜 목록, 호출 후 재오픈하면 빈 목록 -> 비활성일 변화로 검증. 팝업 미오픈 시 안내 문구.
scwin.btn_getDisabledDate_onclick = function () {
    // 팝업 달력 렌더 여부 : 팝업 달력의 날짜 셀(td.w2calendar_col_date) 존재로 판별. (class 기준 - 팝업은 position 레이어라 offsetParent 미사용)
    let calCells = Array.from(document.querySelectorAll("td[class*='w2calendar_col_date']"));

    if (calCells.length === 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("팝업 달력을 한번 오픈해야 정보 가져올 수 있음 (calendar 셀 편집 진입 후 달력 아이콘 클릭)");
        return;
    }

    let disabledDates = calCells.filter(function (td) {
        return td.classList.contains("w2calendar_date_disable");
    }).map(function (td) {
        return td.textContent.trim();
    });

    wf_body_bottom.getObj("scwin").setReturnValue("취소선 적용일 : " + disabledDates);
}
